-- ============================================================================
-- 9999_zzzzzzzzzzzzzzzzzzz_roles_collision_repair.sql
--
-- WHY THIS EXISTS
-- `roles` is declared with CREATE TABLE IF NOT EXISTS in both
-- 000_base_schema.sql (id, name, description, permissions, created_at only)
-- and 014_platform_foundation_modules.sql (adds is_system_role, level,
-- metadata, updated_at). 000 runs first, so on every real database its
-- narrower shape wins and 014's CREATE TABLE silently no-ops - found via
-- docs/registry/06_DUPLICATION_REPORT.md, generated by
-- tools/engineering-registry.js.
--
-- This is a live bug: roleManagementService.js (backend/src/routes/
-- roleManagementRoutes.js, mounted at /api/v1/roles, verified real and
-- reachable 2026-08-28) queries `r.is_system_role` in getRoles() and the
-- module registry's modules/M004_ROLE_MANAGEMENT service references
-- `level`/`metadata` - both would throw "column does not exist" on first
-- real query against a database where only 000's shape ever ran.
--
-- 000-071 are protected core migrations (see CLAUDE.md) - not edited here.
-- Purely additive and idempotent: adds the missing columns/indexes if
-- absent, no-ops if 014's shape already won (fresh databases where 014 runs
-- before anything else touches `roles`, or if this repair already ran).
-- ============================================================================

ALTER TABLE roles ADD COLUMN IF NOT EXISTS is_system_role BOOLEAN DEFAULT false;
ALTER TABLE roles ADD COLUMN IF NOT EXISTS level INTEGER DEFAULT 0;
ALTER TABLE roles ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}';
ALTER TABLE roles ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

CREATE INDEX IF NOT EXISTS idx_roles_system ON roles(is_system_role);
CREATE INDEX IF NOT EXISTS idx_roles_level ON roles(level);
